#!/usr/bin/env python3
"""Build a self-contained, offline illustrated user book from real host captures."""
from pathlib import Path
import base64
import html
import json

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'dist'

def figure(name, caption, alt):
    p = ROOT / 'docs/screenshots' / (name + '.png')
    data = base64.b64encode(p.read_bytes()).decode()
    return f'<figure><button class="picture" type="button" aria-label="Enlarge screenshot: {html.escape(alt)}"><img loading="lazy" src="data:image/png;base64,{data}" alt="{html.escape(alt)}"></button><figcaption>{caption} <span>Click to enlarge.</span></figcaption></figure>'

chapters = []
def chapter(ident, title, deck, body):
    chapters.append((ident, title, deck, body))

chapter('start', 'Start here', 'A practical field guide for your personal Mac build.', '''
<p class="lead">Install once, add the keyer in Fusion, choose the input encoding, then inspect the matte. The GPU engine starts automatically.</p>
<aside><strong>Release status</strong><p>This personal beta is under qualification. Read <a href="NATIVE_QUALIFICATION.md">the acceptance report</a> for the delivered installer. Native 1080p has extensive real MPS and Resolve evidence; that does not establish every required release gate. Keep important work backed up and review your exports.</p></aside>
<div class="route"><a href="#install"><b>01</b>Install</a><a href="#first-key"><b>02</b>Make a key</a><a href="#playback"><b>07</b>Cache for playback</a><a href="#deliver"><b>08</b>Export</a></div>
<h3>What you need</h3><p>An Apple Silicon Mac, sufficient local storage, DaVinci Resolve Studio, the offline installer and a short test shot. The measured machine is an M5 Pro with 48 GB memory, macOS 26.3.2 and Resolve Studio 21.1.1 build 10. Other machines and versions need their own qualification.</p>
<p>The installer contains the private runtime and models. Normal use needs no Python, model download, Terminal window or manually started worker. The Manager is optional maintenance.</p>
<h3>How to read this book</h3><p>Use the bookmarks on the left, the chapter links below each page, or your browser’s Find command. Every screenshot is an actual capture from this Mac. Some show the historical test-project name; the effect to add is always <strong>CorridorKey2.0 hp beta</strong>. Click a screenshot to inspect it. Print / Save PDF creates a paper-friendly book.</p>''')

chapter('install', 'Install and verify', 'Use the normal macOS Installer flow.', '''
<ol><li>Save your work and quit DaVinci Resolve and Fusion.</li><li>Open the delivered <strong>CorridorKeyMac-…-arm64-Offline.pkg</strong>.</li><li>Choose the startup disk and continue. Approve the normal macOS administrator prompt locally.</li><li>Wait for <strong>The installation was successful</strong>, then close Installer.</li><li>Open <strong>CorridorKey2.0 hp beta Manager</strong> in Applications and click <strong>Verify</strong>. A successful inventory check confirms installed files; GPU inference is checked separately on first use.</li><li>Reopen Resolve. Keep the offline package somewhere safe for repair.</li></ol>
<p>This private package is unsigned and its executable code is ad-hoc signed. It is not notarized. Use the normal macOS trust flow if requested; do not disable system protections.</p>
''' + figure('manager-verify', 'Manager → Verify. The build identifier in this capture is a historical qualification build.', 'Manager with a successful installed-file verification') + '''
<h3>If installation stops</h3><p>Close Resolve and Fusion before retrying. Check free disk space: installation needs room for staging and rollback as well as installed assets. Unsupported destinations are refused. Do not move individual runtime or model folders.</p>''')

chapter('first-key', 'Make your first key', 'Start with a short copy of a shot.', '''
<ol><li>Put a green- or blue-screen clip on a timeline and open its <strong>Fusion</strong> page.</li><li>Select the source node. Press <kbd>Shift</kbd> + <kbd>Space</kbd>, search for <strong>CorridorKey</strong>, select <strong>CorridorKey2.0 hp beta</strong>, and click <strong>Add</strong>.</li><li>Confirm the flow: <strong>MediaIn → CorridorKey → MediaOut</strong>. Put any required color transform before the keyer.</li><li>Select the keyer and open <strong>Inspector → Controls</strong>. Choose the actual <strong>Input Encoding</strong> described in the next chapter.</li><li>Leave <strong>Mode: Single Frame</strong>, <strong>Output: Premultiplied</strong>, and <strong>Despill Amount: 0</strong> for the first inspection. Leave hints unused for ordinary opaque camera footage.</li><li>View the result. First use loads the models and performs a real GPU check before processing your frame. Allow it to finish.</li></ol>
''' + figure('add-effect', 'Choose the hp beta entry. The official plugin can coexist with this personal build.', 'Fusion Add Tool dialog showing the official and hp beta effect names') + figure('controls', 'A real keyed frame, the Inspector groups, and the Fusion flow on this Mac.', 'Actual Fusion keyer and controls beside a keyed green-screen subject') + '''
<p>An inference error stops the render and reports a problem. It does not silently substitute the original source. <strong>Original</strong> is an explicit preview choice.</p>''')

chapter('input', 'Set color and resolution', 'Match the image arriving at the node.', '''
<table><thead><tr><th>Input Encoding</th><th>Use when the node receives</th></tr></thead><tbody><tr><td>sRGB</td><td>sRGB transfer curve with sRGB / Rec.709 primaries.</td></tr><tr><td>Scene-linear Rec.709</td><td>Linear RGB with Rec.709 / sRGB primaries.</td></tr><tr><td>Rec.709 Gamma 2.4</td><td>A gamma 2.4 display image with Rec.709 primaries.</td></tr></tbody></table>
<p>Choose the encoding <em>after</em> upstream transforms. A camera label alone is insufficient. Convert S-Log3 / S-Gamut, DaVinci Wide Gamut, ACES, PQ or HLG deliberately before the keyer. Gamma 2.4 is not the Rec.709 camera OETF. There is no automatic color-space detection.</p>
<h3>Internal Resolution</h3><p><strong>Full</strong> runs at the node’s canvas size. <strong>Two Thirds</strong>, <strong>Half</strong> and <strong>Quarter</strong> calculate a smaller key and upscale it to that canvas. These are visible quality choices, saved in the project.</p>
<p>This beta refuses internal dimensions above <strong>2048 × 1152</strong>. For a 3840 × 2160 source, Half explicitly calculates at 1920 × 1080. Native UHD failed quality qualification and is not supported by a Full claim. No failed Full render is automatically downgraded.</p>
<ol><li>Use Half or Quarter while adjusting the shot.</li><li>For a native 1080p final, return to Full before analysis and export.</li><li>For a larger canvas, choose a supported profile explicitly and inspect the upscaled edges at 100%.</li></ol>
<aside><strong>Composition canvas</strong><p>Resolve’s project resolution alone may not resize MediaIn in Fusion. Check the dimensions arriving at the keyer; insert an explicit resize before it when qualifying a 1920 × 1080 key.</p></aside>''')

chapter('matte', 'Inspect and composite', 'Check edges before judging the finished shot.', '''
<ol><li>In <strong>Output</strong>, select <strong>Matte</strong>. Inspect hair, gaps, motion blur and semi-transparent objects across several frames.</li><li>Select <strong>Straight FG</strong> to inspect recovered foreground color without alpha multiplication.</li><li>Return to <strong>Premultiplied</strong> for compositing and alpha export.</li><li>Add a <strong>Merge</strong>. Connect the keyer to its foreground input and your replacement background to its background input. Connect Merge to MediaOut.</li><li>Inspect over black, white and a saturated background at 100%. Check for edge halos, missing detail and spill.</li></ol>
<div class="flow" role="img" aria-label="Keyed source enters Merge foreground; background enters Merge background; Merge feeds MediaOut"><span>Source → Keyer</span><span>↓ Foreground<br><b>Merge → MediaOut</b><br>↑ Background</span><span>Replacement background</span></div>
<p><strong>Premultiplied</strong> already associates RGB with alpha once. Do not multiply it again. Matte, Straight FG and Original are opaque inspection outputs and are not alpha-bearing final keys.</p>
<table><tr><th>Output control</th><th>Purpose</th></tr><tr><td>White Point</td><td>Remaps alpha, clamped to 0–1. The neutral value is 1. Inspect thin detail after changes.</td></tr><tr><td>Keep Solid Detail</td><td>Restores original RGB where raw model alpha exceeds 0.95, before additional despill.</td></tr><tr><td>Linear Output</td><td>Returns scene-linear RGB; alpha is unchanged. Match downstream color handling.</td></tr><tr><td>Show Result</td><td>Off selects Original; on selects Premultiplied. It changes the saved output choice.</td></tr></table>
<p>For linear-light compositing, feed scene-linear Rec.709 into the keyer and keep the Merge in the same linear representation. A checkerboard demonstrates transparency, not correct compositing by itself.</p>''')

chapter('temporal', 'Analyze a continuous shot', 'Temporal processing needs an exact range and stable inputs.', '''
<ol><li>Finish upstream retiming, resize and color decisions. Bake variable or fractional retiming first.</li><li>Set <strong>Shot Start</strong> and <strong>Shot End</strong> to inclusive integer frames at this node. For 60 frames starting at 0, use 0 and 59. Include one continuous shot, with no cut.</li><li>Open <strong>Time Awareness</strong>, select <strong>Mode: Temporal</strong>, and begin with <strong>Window: 4</strong>.</li><li>Set the final Internal Resolution before analysis. Click <strong>Analyze Shot</strong> to advance the saved analysis revision.</li><li>Let Resolve acquire the shot. A capture-verification message may ask you to render again. Keep upstream settings unchanged and repeat the render to verify the same input set before processing.</li><li>Wait for the actual analysis to finish before playback or export. Review beginning, middle, end and fast motion.</li></ol>
<aside><strong>Capture safety is under validation</strong><p>An acquisition-phase upstream edit exposed a mixed-source bug in 0.9.6. The acceptance report identifies whether the delivered revision passed its replacement test. Do not edit the source, grade, hints or timing during analysis. A verification prompt is not a finished key.</p></aside>
<p>The range is 2–240 frames. Shot End −1 uses the available source range; set an explicit end for predictable analysis. Split longer footage into continuous ranges. Node-input frame numbers can differ from timeline timecode, especially after trims or offsets.</p>
<h3>Memory and window controls</h3><table><tr><th>Control</th><th>Meaning</th></tr><tr><td>Window</td><td>Actual temporal context. Default 4 uses overlapping 4-frame windows with a 2-frame stride. Larger settings need more memory and separate validation.</td></tr><tr><td>GPU Limit</td><td>Allocator ceiling relative to Metal’s recommended working set. Auto uses 80%; it does not report currently free RAM.</td></tr><tr><td>Low GPU Memory</td><td>Uses smaller equivalent execution chunks. It preserves selected resolution, temporal window and float32 precision.</td></tr><tr><td>Reuse Captures</td><td>Reuses verified input captures across explicit reanalysis. Unchanged playback already reuses captures.</td></tr><tr><td>Cancel</td><td>Cancels this node’s wait. Resolve’s render cancel is the tested responsive host path. An already executing GPU operation can take time to finish.</td></tr></table>
<p>Source and hint changes invalidate their dependent outputs. <strong>Analyze Shot</strong> also advances a saved render revision so the host can refresh its own cached output. Always refill playback cache after creative changes.</p>''')

chapter('hints', 'Refine hints and despill', 'Start with the model result; add guidance only when useful.', '''
<h3>Supply a useful hint</h3><ol><li>Create a rough, aligned subject matte that retains the original RGB.</li><li>Choose <strong>Source Alpha</strong> if the matte is carried in Source alpha, or connect a separate RGBA Hint input and choose <strong>Hint Alpha</strong> or <strong>Hint Luma</strong>.</li><li>Keep the Hint’s dimensions, origin and timing identical to Source. Enable <strong>Use Hint</strong>.</li><li>Adjust <strong>Hint Strength</strong>; new nodes start at 0.75. Compare with Use Hint off.</li></ol>
<p>An ordinary camera clip with alpha 1 everywhere is not a useful subject hint. <strong>None / Legacy</strong> preserves saved-project behavior; leave <strong>Legacy Alpha</strong> off unless intentionally using that older switch.</p>
<p><strong>Hint Frames: All Frames</strong> consumes each aligned hint. <strong>Reference Frame</strong> uses a chosen integer frame and propagates in Temporal mode, with Window 2 or higher. Leave Reference Frame blank to use Shot Start, type an in-range integer, or click <strong>Set Reference</strong> at that frame. A later reference propagates outward in both directions; inspect that variant separately. <strong>Internal Hint</strong> controls trust in the neural hint carried between windows, independently of your external matte.</p>
<h3>Reduce remaining screen color</h3><ol><li>Begin at <strong>Despill Amount: 0</strong>. The model already recovers foreground color.</li><li>Increase Amount gradually while watching skin, fabric and transparent edges.</li><li>Use <strong>Auto</strong>, <strong>Green</strong>, <strong>Blue</strong> or <strong>Picked</strong> for the additional correction. Auto estimates the backing from predicted-background pixels.</li><li>Choose <strong>Average</strong>, <strong>Double Limit</strong> or <strong>Neutral</strong>, then compare against the uncorrected frame.</li></ol>
<p><strong>Freeze Color</strong> copies the last completed render’s detected backing into Picked Color and selects Picked. Render a key first. These controls are post-processing; they do not select a different neural model.</p>''')

chapter('playback', 'Get smooth playback', 'Pre-render the key; live full-model processing is an offline operation.', '''
<p class="lead">Full 1080p neural inference is around 3 seconds per distinct Single Frame on the measured Mac. Smooth playback comes from a completed Resolve cache.</p>
<h3>Fusion viewer: Cache to Disk</h3><ol><li>Finish the shot’s settings and analysis. Set the composition render range to the shot.</li><li>Right-click the keyer node and choose <strong>Cache to Disk</strong>.</li><li>Enable caching and choose a writable local path ending in <strong>DiskCache0000.raw</strong>. Create the parent folder first if needed.</li><li>Leave <strong>Lock Cache</strong>, <strong>Lock Branch</strong> and <strong>Use Network</strong> off.</li><li>Click <strong>Pre-render</strong> and wait for every frame. If capture verification stops the first pass, repeat after checking the message.</li><li>Play after completion. After any source or key change, let the unlocked cache invalidate and refill.</li></ol>
<p>The actual 0.9.6 test reached approximately <strong>24.5 fps</strong> in a 25 fps Fusion project after native disk caching. Live temporal viewing with plugin results already cached was only about 1.6–1.9 fps because the host still acquired the shot. These are different measurements.</p>
<h3>Edit timeline: User render cache</h3><ol><li>Choose <strong>Playback → Render Cache → User</strong>.</li><li>Right-click the timeline clip and choose <strong>Render Cache Fusion Output → On</strong>.</li><li>Leave Resolve idle until the cache bar becomes blue, then play.</li></ol>
<h3>Practical speed choices</h3><p>Use explicit Half or Quarter while adjusting edges, shorten the selected range, and avoid unnecessary reanalysis. Return to your intended final profile and refill cache before export. Preview settings are saved; they do not switch back automatically.</p>
<aside><strong>Final precision</strong><p>Resolve’s playback cache is separate from the plugin’s float32 result cache. Leave <strong>Use render cached images</strong> off for a precision-critical final unless that Resolve cache format has been qualified for your HDR / alpha requirements.</p></aside>''')

chapter('deliver', 'Export the final result', 'Choose whether you need a transparent key or a finished composite.', '''
<ol><li>Inspect the intended final Internal Resolution, input encoding, hint settings, shot range and Output. Reanalyze and refill any invalidated cache.</li><li>For transparent output, connect the keyer’s <strong>Premultiplied</strong> output to MediaOut. For a finished replacement background, connect Merge to MediaOut instead.</li><li>Open <strong>Deliver</strong>, choose <strong>Custom Export</strong>, and set the intended frame range and resolution.</li><li>For a floating-point alpha master, choose <strong>EXR</strong>, <strong>RGBA (float 32)</strong>, and enable <strong>Export Alpha</strong>. Set compression and destination as needed.</li><li>For a movie with alpha, use an alpha-capable codec such as <strong>ProRes 4444</strong> and enable Export Alpha. Confirm the available codec settings in your Resolve version.</li><li>In Advanced Settings, leave <strong>Use render cached images</strong> off for the unqualified cache-format route.</li><li>Add to Render Queue and start the job. Wait for Completed, then reimport and inspect the exported alpha, frame count, timing and several edges.</li></ol>
''' + figure('deliver', 'Actual Deliver setup: 1920 × 1080, EXR RGBA float32, Export Alpha enabled.', 'Resolve Deliver page with float32 RGBA EXR export and alpha checked') + '''
<p>A black viewer background alone does not mean alpha is missing. Inspect alpha or composite the reimport over another background. H.264 / H.265 are not the demonstrated transparent-master route.</p>
<p>Actual native tests exported 60-frame Single Frame and Temporal EXR sequences, plus a 12-frame 30000/1001 ProRes 4444 alpha movie across a cut with independent keyers. The acceptance report records exact build identity and comparisons.</p>''')

chapter('maintenance', 'Verify, repair and storage', 'Use the Manager when maintenance is needed.', '''
<table><tr><th>Manager action</th><th>What to do</th></tr><tr><td>Verify</td><td>Checks the installed inventory. A file-integrity success is separate from inference and visual qualification.</td></tr><tr><td>GPU status</td><td>Prepares the real engine and reports loading, actual device, completed model work and errors.</td></tr><tr><td>Release GPU</td><td>Releases an idle engine. The next render restarts it automatically. Active work blocks unsafe maintenance.</td></tr><tr><td>Storage / Open Cache</td><td>Shows storage use or opens this user’s product cache.</td></tr><tr><td>Choose Cache…</td><td>Selects a writable cache location for this user, safely draining an idle engine first. Reconnect an unavailable cache volume or choose another.</td></tr><tr><td>Support File</td><td>Creates local diagnostic metadata without media, tokens or automatic uploads.</td></tr><tr><td>Repair…</td><td>Select the matching offline installer; the Manager verifies its payload and executable installer logic before opening Installer.</td></tr></table>
<h3>Repair a missing or corrupt file</h3><ol><li>Save your work and quit Resolve and Fusion.</li><li>Open Manager and click <strong>Verify</strong>; retain the error details.</li><li>Click <strong>Repair…</strong> and locate the matching delivered offline package, including if you moved it.</li><li>Wait for complete package verification, then approve normal Installer authorization.</li><li>After installation, run Verify again and reopen your test project.</li></ol>
''' + figure('manager-busy', 'A real active-work refusal. Finish or cancel the render before maintenance.', 'Manager refusing GPU release while a model job is active') + '''
<p>Do not edit signed runtime files or move model folders by hand. <strong>Clear Shot Cache</strong> removes this node’s unshared captures/results; shared entries are retained. A cold render rebuilds missing cache data.</p>''')

chapter('uninstall', 'Uninstall safely', 'Remove this product through the installed workflow.', '''
<ol><li>Save your projects and quit Resolve and Fusion.</li><li>Open <strong>CorridorKey2.0 hp beta Manager</strong>.</li><li>Choose <strong>Keep Models</strong> to retain the shared model set for reinstall, or <strong>Remove All</strong> to remove this product’s models too.</li><li>Approve the normal macOS Installer prompt and wait for completion.</li><li>Reopen Resolve and check that the hp beta effect is absent from newly added effects. Saved nodes may appear unavailable until you reinstall.</li></ol>
<p>The installed removal packages live in <code>/Library/Application Support/HarvestPictures/CorridorKeyMac/Maintenance/</code>. The delivered folder also contains both uninstall packages. Removal does not require the original downloaded offline installer.</p>
<p>The scoped removal targets this product’s plugin, Manager and runtime. It preserves the official CorridorKey plugin, other OFX plugins, source footage and Resolve projects. Per-user reconstructable cache is separate; after closing all engines, use Manager’s Open Cache location to identify product cache rather than deleting Resolve’s general CacheClip folder.</p>
<aside><strong>Qualification record</strong><p>Read QA-37 and QA-38 in the accompanying report for the actual repair and uninstall test results. Workflow availability by itself is not a passed native maintenance test.</p></aside>''')

chapter('trouble', 'Troubleshooting and limits', 'Follow the reported state; preserve the original footage.', '''
<table><tr><th>Symptom</th><th>Next step</th></tr><tr><td>Effect absent</td><td>Reopen Resolve after installation. Run Manager Verify. Search the exact hp beta name; the official effect has a separate entry.</td></tr><tr><td>First render takes time</td><td>Check GPU status. Models load and a real GPU check precedes your first frame. Subsequent frames still take offline processing time.</td></tr><tr><td>Playback is very slow</td><td>Follow the native Cache to Disk workflow in chapter 07; wait for all frames. Use explicit preview profiles while adjusting.</td></tr><tr><td>Capture verification prompt</td><td>Keep upstream settings unchanged and render again. Check the acquisition-safety status in the report before relying on Temporal.</td></tr><tr><td>Memory error</td><td>Close unnecessary GPU-heavy work. Choose a lower Internal Resolution or a shorter validated window explicitly. Reinspect quality.</td></tr><tr><td>Unsupported internal size</td><td>Choose Half / Quarter or resize before the keyer. Native UHD Full is unqualified.</td></tr><tr><td>Halo / wrong color</td><td>Check input transfer function and primaries, premultiplication, downstream transforms and despill. Review over black and white.</td></tr><tr><td>Opaque alpha export</td><td>Use Premultiplied output, an alpha-capable format, and Export Alpha. Matte / Straight FG / Original are opaque previews.</td></tr><tr><td>Maintenance blocked</td><td>Finish or cancel active work, save, then close Resolve and Fusion. Do not kill unrelated processes.</td></tr><tr><td>Cache volume unavailable</td><td>Reconnect it or use Choose Cache. Errors are explicit; do not replace private folders with loose symlinks.</td></tr></table>
<h3>Limits to keep in view</h3><p>Live full-model playback is not real time. Larger windows, new memory profiles, other Macs, other host versions and transferred-package trust paths need their own checks. No automatic CPU neural fallback or automatic final-quality reduction is provided. Glass, blur and fine detail need shot-specific review; no arbitrary-footage perfect-matte promise is made.</p>
<p>Keep this book with <a href="NATIVE_QUALIFICATION.md">NATIVE_QUALIFICATION.md</a>, <a href="PERFORMANCE.md">PERFORMANCE.md</a>, <a href="KNOWN_LIMITATIONS.md">KNOWN_LIMITATIONS.md</a>, the checksums, source and installer. These local files contain the actual release scope.</p>''')

CSS = r'''
:root{--paper:#fffdf8;--ink:#182c32;--muted:#5d7073;--accent:#167264;--line:#d9e0d9;--wash:#edf3ed;--rail:280px}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:35px}body{margin:0;background:#e9ece7;color:var(--ink);font:17px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--accent);text-underline-offset:3px}nav a{text-decoration:none}button{font:inherit;cursor:pointer}#rail{position:fixed;inset:0 auto 0 0;width:var(--rail);padding:32px 24px;background:#142e32;color:#e9f0e9;overflow:auto}#rail .brand{font-size:13px;letter-spacing:.11em;text-transform:uppercase;color:#97bcb2}#rail h1{font:600 25px/1.2 Georgia,serif;margin:12px 0 8px}#rail .edition{font-size:12px;color:#b7cbc5}#rail h2{font-size:12px;letter-spacing:.15em;text-transform:uppercase;margin:28px 0 12px;color:#97bcb2}#rail a{display:block;padding:7px 8px;border-radius:5px;color:#d4e2dc;font-size:14px;line-height:1.45;margin-bottom:3px}#rail a.current,#rail a:hover{background:#294b4c;color:white}#rail a span{font-variant-numeric:tabular-nums;color:#89b6a5;margin-right:9px}#rail button{margin-top:20px;background:transparent;border:1px solid #527371;color:white;padding:9px 13px;border-radius:4px;font-size:13px}main{margin-left:var(--rail);padding:38px clamp(18px,4vw,70px) 60px;max-width:1460px}.chapter{background:var(--paper);padding:clamp(26px,5vw,68px);margin:0 0 34px;border:1px solid var(--line);box-shadow:0 8px 30px #182c3206;border-radius:3px;scroll-margin-top:30px}.chapter .kicker{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--accent);font-weight:700}.chapter h2{font:500 clamp(30px,3.6vw,47px)/1.12 Georgia,serif;letter-spacing:-.025em;margin:12px 0 15px;max-width:720px}.deck{font-size:19px;color:var(--muted);line-height:1.5;border-bottom:1px solid var(--line);padding-bottom:24px;margin-bottom:28px}.lead{font-size:22px;line-height:1.55}h3{font-size:19px;line-height:1.35;margin:32px 0 12px}p{margin:15px 0}ol{padding-left:25px}li{padding-left:6px;margin:13px 0}strong{font-weight:650}aside{background:var(--wash);border-left:3px solid var(--accent);padding:18px 22px;margin:26px 0;font-size:15px}aside p{margin:7px 0 0}table{border-collapse:collapse;width:100%;font-size:15px;margin:22px 0;line-height:1.55}th,td{border-bottom:1px solid var(--line);padding:13px 14px;text-align:left;vertical-align:top}th{background:var(--wash);font-weight:650}td:first-child{width:28%;font-weight:600}figure{margin:30px 0}.picture{background:#1f2228;border:0;border-radius:5px;width:100%;padding:8px;display:block;overflow:hidden}.picture img{display:block;max-width:100%;max-height:650px;object-fit:contain;margin:auto}.picture:focus-visible{outline:3px solid var(--accent);outline-offset:4px}figcaption{font-size:13px;color:var(--muted);margin-top:10px;line-height:1.5}figcaption span{white-space:nowrap;color:var(--accent)}kbd{border:1px solid #bcc8c1;border-radius:4px;padding:2px 7px;font-size:14px;background:white}code{font:12px/1.7 ui-monospace,monospace;overflow-wrap:anywhere}.route{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:28px 0}.route a{display:block;background:var(--wash);padding:17px;text-decoration:none;font-size:15px}.route b{display:block;color:var(--muted);font-size:12px}.flow{display:flex;flex-direction:column;align-items:center;text-align:center;border:1px solid var(--line);padding:22px;background:var(--wash);gap:10px;line-height:1.55;font-size:15px}.flow span{padding:10px 20px;border:1px solid #c1d3c9;border-radius:4px;background:var(--paper)}.page-nav{display:flex;justify-content:space-between;gap:20px;border-top:1px solid var(--line);margin-top:36px;padding-top:18px;font-size:13px}.page-nav a{max-width:48%}.page-nav .next{text-align:right}#progress{position:fixed;top:0;left:var(--rail);right:0;height:3px;background:var(--accent);transform-origin:left;transform:scaleX(0);z-index:5}dialog{border:0;background:#122b30;padding:18px;border-radius:6px;max-width:96vw;max-height:96vh;color:white}dialog::backdrop{background:#071719dd}dialog img{display:block;max-width:90vw;max-height:82vh;object-fit:contain}dialog button{display:block;margin:12px 0 0 auto;background:#fffdf8;color:#182c32;border:0;padding:6px 20px;border-radius:3px}footer{color:var(--muted);font-size:13px;padding:0 8px}a:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:850px){:root{--rail:0px}#rail{position:relative;width:auto;padding:22px}#rail nav{display:grid;grid-template-columns:1fr 1fr;gap:2px 12px}#rail h2{margin-top:20px}#rail a{font-size:13px;padding:5px}main{margin:0;padding:18px 12px}.chapter{padding:25px 20px;margin-bottom:18px}.chapter h2{font-size:33px}.lead{font-size:20px}table{font-size:13px}th,td{padding:10px 7px}#progress{left:0}.route{grid-template-columns:1fr 1fr}body{font-size:16px}}@media print{@page{size:A4;margin:18mm 16mm}html{scroll-behavior:auto}body{background:white;color:black;font-size:10pt;line-height:1.5}#rail{position:static;background:white;color:black;width:auto;padding:0;break-after:page}#rail h1{font-size:26pt}#rail a,#rail .edition,#rail .brand{color:black}#rail nav{display:block;columns:2}#rail a{font-size:10pt}#rail button,#progress,dialog,.page-nav,figcaption span{display:none!important}main{margin:0;padding:0;max-width:none}.chapter{box-shadow:none;border:0;border-radius:0;padding:0;margin:0;break-before:page}.chapter h2{font-size:28pt}.deck{font-size:12pt;padding-bottom:14px;margin-bottom:18px}.lead{font-size:14pt}h3{font-size:12pt;break-after:avoid}figure,table,aside{break-inside:avoid}.picture{padding:0;background:white}.picture img{max-height:105mm}.route{display:none}a{color:inherit}th,td{padding:7px;font-size:9pt}li{margin:8px 0}aside{padding:12px;font-size:10pt}footer{margin-top:18px} }
'''

def main():
    OUT.mkdir(exist_ok=True)
    nav=''.join(f'<a href="#{c[0]}"><span>{i:02}</span>{c[1]}</a>' for i,c in enumerate(chapters))
    pages=[]
    for i,(ident,title,deck,body) in enumerate(chapters):
        prev=f'<a href="#{chapters[i-1][0]}">← {chapters[i-1][1]}</a>' if i else '<span></span>'
        nex=f'<a class="next" href="#{chapters[i+1][0]}">{chapters[i+1][1]} →</a>' if i+1<len(chapters) else '<a href="#start">Back to start ↑</a>'
        pages.append(f'<section class="chapter" id="{ident}" aria-labelledby="h-{ident}"><div class="kicker">Chapter {i:02} · User book</div><h2 id="h-{ident}">{title}</h2><p class="deck">{deck}</p>{body}<nav class="page-nav" aria-label="Chapter navigation">{prev}{nex}</nav></section>')
    js=r'''const links=[...document.querySelectorAll('#rail nav a')];const sections=[...document.querySelectorAll('.chapter')];function highlight(){let current=sections[0];for(const s of sections){if(s.getBoundingClientRect().top<innerHeight*.36)current=s;}links.forEach(a=>{const on=a.hash==='#'+current.id;a.classList.toggle('current',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});const d=document.documentElement;document.querySelector('#progress').style.transform='scaleX('+Math.min(1,scrollY/Math.max(1,d.scrollHeight-innerHeight))+')';}addEventListener('scroll',highlight,{passive:true});highlight();document.querySelector('#print').addEventListener('click',()=>print());const dlg=document.querySelector('dialog');document.querySelectorAll('.picture').forEach(b=>b.addEventListener('click',()=>{const im=b.querySelector('img');dlg.querySelector('img').src=im.src;dlg.querySelector('img').alt=im.alt;dlg.showModal();}));dlg.querySelector('button').addEventListener('click',()=>dlg.close());dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close();});'''
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>CorridorKey2.0 hp beta — User Book</title><style>{CSS}</style></head><body><aside id="rail" aria-label="Book bookmarks"><div class="brand">Harvest Pictures · Personal tools</div><h1>CorridorKey2.0<br>hp beta</h1><div class="edition">The illustrated user book · Offline edition</div><h2>Bookmarks</h2><nav aria-label="Table of contents">{nav}</nav><button id="print" type="button">Print / Save PDF</button></aside><div id="progress" aria-hidden="true"></div><main>{''.join(pages)}<footer>Personal-use documentation. Screenshots captured in the installed Resolve and Manager on this Mac. Qualification claims are governed by the accompanying exact-artifact report. No external scripts, fonts or image requests.</footer></main><dialog aria-label="Enlarged screenshot"><img alt=""><button type="button">Close</button></dialog><script>{js}</script></body></html>'''
    dest=OUT/'CorridorKey2.0-hp-beta-User-Book.html'
    dest.write_text(doc)
    print(f'{dest}: {dest.stat().st_size:,} bytes; {len(chapters)} chapters; {len(nav)} TOC characters')

if __name__=='__main__':main()
